{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of the packing plan — for example, minimize the number of containers used, minimize total transport cost, or maximize the total amount of goods shipped?"
  ],
  "rationale": "The response asks for a single policy choice (the objective function) and presents examples of that choice, so it is one atomic clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the goal to ship all available goods (all 120 A, 90 B, 300 C, 90 D, 120 E), or is it acceptable to leave some goods unshipped if that reduces the number of containers?"
  ],
  "rationale": "The response presents a single binary choice regarding the shipping objective (ship all vs. minimize containers), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available unlimited, or is there a fixed maximum number of containers that can be used?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability limit of containers."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single container hold multiple goods types together (e.g., a mix of A, B, C, D, E), or must each container be dedicated to only one goods type?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding container composition."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods units indivisible (each unit must be whole, so container loads are integer numbers of units), or can units be split fractionally?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of goods units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Does this mean every container that is used must contain at least 12 D units (which would limit the plan to at most 7 containers), or is the 12-unit D minimum only required for containers that actually contain any D?"
  ],
  "rationale": "The response presents a single clarification question asking for a policy choice between two interpretations of the constraint."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Does this apply to every container that contains A, or only to containers that contain A in some minimum quantity?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the scope of the rule (all containers vs. minimum quantity), which constitutes one independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units of a single goods type can go into one container, or can a container hold all 120 units of A (or all 300 of C) if the weight allows?"
  ],
  "rationale": "The response asks a single clarification question regarding unit limits per container, presented as a choice between a limit existing or the ability to hold all units if weight permits."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any requirement that each container must contain at least one unit of every goods type, or can a container contain only some types (e.g., only B, D, and E) as long as the weight and D rules are satisfied?"
  ],
  "rationale": "The response asks a single clarification question regarding the composition constraints of the containers."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is it acceptable for the model to use fewer than 7 containers (e.g., 6) if that still ships all goods, or must it use exactly 7?"
  ],
  "rationale": "The response asks a single clarification question regarding whether the number of containers used must be exactly 7 or can be fewer, provided all goods are shipped."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any other constraints or requirements I should know about, such as specific container types, loading order, or cost considerations beyond the number of containers?"
  ],
  "rationale": "The response asks a single open-ended question about additional constraints or requirements. Although it lists examples (container types, loading order, cost), it frames them as examples of the same general inquiry ('other constraints or requirements'), which constitutes one semantic question."
}
